const $=s=>document.querySelector(s);let section='launch',rows=[],uploads={},auditScenario='pass';const req=(id,el=id)=>`data-req-id="${id}" data-req-element="${el}"`;const icons=['<svg viewBox="0 0 34 34" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M7 3h13l7 7v21H7z"/><path d="M20 3v8h7M11 17h12M11 22h12M11 27h8"/></svg>', '<svg viewBox="0 0 34 34" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 7h26v22H4zM4 14h26M4 21h26M12 7v22M22 7v22"/></svg>', '<svg viewBox="0 0 34 34" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 7h18M12 17h18M12 27h18"/><circle cx="5" cy="7" r="1"/><circle cx="5" cy="17" r="1"/><circle cx="5" cy="27" r="1"/></svg>', '<svg viewBox="0 0 34 34" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="4" width="26" height="26" rx="2"/><path d="m9 16 6 7L26 11"/></svg>', '<svg viewBox="0 0 34 34" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 6 19 3v28L4 28zM21 7h9v21h-9M23 11h5M23 15h5M23 19h5M23 23h5"/></svg>', '<svg viewBox="0 0 34 34" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m13 21 9-9M10 17l-3 3a6 6 0 0 0 9 9l5-5M24 17l3-3a6 6 0 0 0-9-9l-5 5"/></svg>'];const names=['标识管理系统','连接器管理系统','主体身份管理系统','业务节点管理系统','数据目录管理系统','存证服务'];const colors=[['#7599dc','#294e9b'],['#9c79df','#532ca0'],['#6ed8c7','#229a8b'],['#d8b16e','#a4742c'],['#df7777','#a92c30'],['#79a3df','#2d5c9e']];function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2600)}
function nav(){let items=section==='launch'?['快捷入口','鉴权管理','流程中心','区域目录管理系统','应用上架','审核管理']:['系统首页','接入登记审核','业务节点管理','运行监测','系统设置'];$('#sidebar').innerHTML=items.map((n,i)=>`<div class="nav ${section!=='launch'&&((section==='home'&&i===0)||(section==='review'&&i===1))?'active':''}" ${req(i===1?'node.review':'navigation.'+i)} onclick="navigate(${i})"><span>${['↗','▣','▦','▧','◉','◉'][i]}</span>${n}${i?'<em>⌄</em>':''}</div>`).join('')+(section!=='launch'?'<div class="nav" onclick="section=\'launch\';render()"><span>⇤</span>返回快捷入口</div>':'')}
function navigate(i){if(section==='launch'){if(i===0)render();else toast('请从快捷入口进入业务子系统');return}section=i===1?'review':'home';if(i>1){toast('该模块暂不可用');return}render()}
function render(){nav();if(section==='launch'){$('#main').innerHTML=`<div class="launch"><div class="hero"><span class="eyebrow">• LAUNCHPAD</span><h1>快捷入口</h1><p>选择业务子系统，快速开始工作</p></div><div class="cards">${names.map((n,i)=>`<article class="card ${i===3?'business':''}" ${req(i===3?'node.enter':i===4?'catalog.browse':'system.'+i)} onclick="${i===3?"section='home';render()":i===4?"catalogOpen()":"toast('当前系统提供业务节点管理系统')"}"><span class="num">0${i+1}</span><div class="icon" style="--light:${colors[i][0]};--dark:${colors[i][1]}">${icons[i]}</div><h2>${n}</h2><p>业务子系统</p><button class="enter">立即进入</button><span class="arrow">→</span></article>`).join('')}</div></div>`;return}if(section==='home'){$('#main').innerHTML=`<div class="workspace"><div class="crumb">业务节点管理系统 / 系统首页</div><div class="pageheading"><div><h1>业务节点管理系统</h1><span class="muted">统一管理业务节点接入，保障服务合规运行</span></div><span class="muted"></span></div><div class="summary panel" ${req('node.statistics')}><article>接入登记总数<strong>${rows.length}</strong><span class="muted">当前会话</span></article><article>待人工审核<strong>${rows.length}</strong><span class="muted">机器审核通过后进入</span></article><article>已完成审核<strong>0</strong><span class="muted">人工审核完成的登记</span></article></div><div class="panel"><h3>快捷操作</h3><p class="muted">发起业务节点接入登记，完成材料填报与审核</p><button class="btn primary" ${req('node.review')} onclick="section='review';render()">接入登记审核 →</button></div><div class="panel"><h3>接入审核流程</h3><div class="auditsteps">① 填写登记与上传材料　 →　 ② 机器内容审核　 →　 ③ 提交成功　 →　 ④ 人工审核</div><p class="muted">内容安全检查覆盖登记文本及上传材料。模型异常时保留草稿，禁止直接进入人工审核。</p></div></div>`;return}$('#main').innerHTML=`<div class="workspace"><div class="crumb">业务节点管理系统 / 接入登记审核</div><div class="pageheading"><div><h1>接入登记审核</h1><span class="muted">管理接入申请，查看机器审核与人工审核进度</span></div><button class="btn primary" ${req('node.create')} onclick="openForm()">＋ 新增接入注册</button></div><div class="panel"><div class="filters" ${req('node.query')}><label>登记名称</label><input id="search" placeholder="请输入登记名称"><label>审核状态</label><select id="state"><option>全部</option><option>待人工审核</option></select><button class="btn primary" onclick="drawRows()">查询</button><button class="btn" onclick="$('#search').value='';$('#state').selectedIndex=0;drawRows()">重置</button></div><table><thead><tr><th>序号</th><th>登记名称</th><th>所属组织</th><th>服务类型</th><th>版本号</th><th>机器审核</th><th>人工审核状态</th><th>操作</th></tr></thead><tbody id="rows"></tbody></table><div class="pagination">共 ${rows.length} 条　　每页 10 条　　〈 <b>1</b> 〉</div></div></div>`;drawRows()}
function esc(t){return String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function drawRows(){const found=rows.filter(r=>r.name.includes($('#search').value));$('#rows').innerHTML=found.length?found.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.name)}</td><td>${esc(r.org)}</td><td>${esc(r.service||'—')}</td><td>${esc(r.version)}</td><td><span class="status ok">已通过</span></td><td><span class="status">待人工审核</span></td><td><button class="link" onclick="showDetail(${rows.indexOf(r)})">查看详情</button></td></tr>`).join(''):'<tr><td colspan="8" class="empty">▤<br><br>暂无接入登记记录<br><br><span class="muted">点击「新增接入注册」发起申请</span></td></tr>'}
const fields=[['name','登记名称','请输入业务节点登记名称',true],['operator','运营机构名称','请输入运营机构名称'],['org','所属组织','请选择所属组织',true],['credit','统一社会信用代码','请输入统一社会信用代码'],['service','服务类型','请选择服务类型'],['version','版本号','请输入版本号，如 1.0.0 或 v1.0.0',true],['date','经营时间','请选择经营时间'],['legal','法人姓名','请输入法人姓名'],['phone','法人联系方式','请输入法人联系方式'],['idcard','法人身份证号','请输入法人身份证号'],['address','物理地址','请输入业务节点物理地址']];function field(f){return `<div class="field" ${req('node.field.'+f[0])}><label class="${f[3]?'required':''}">${f[1]}</label>${f[0]==='service'?'<select name="service"><option value="">请选择服务类型</option><option>数据服务</option><option>应用服务</option><option>基础设施服务</option></select>':`<input name="${f[0]}" placeholder="${f[2]}" ${f[3]?'required':''} ${f[0]==='date'?'type="date"':''} ${f[0]==='address'?'maxlength="100"':''}>`}</div>`}function upload(label,key,required=false){return `<label class="upload">${label}<input type="file" hidden accept=".pdf,.png,.jpg,.jpeg,.doc,.docx" onchange="onFile(this,'${key}')"></label><span class="files" id="file-${key}"></span>`}
function openForm(){uploads={};$('#overlay').innerHTML=`<div class="veil"><section class="modal"><div class="modalhead">新增接入注册<button class="close" onclick="closeForm()">×</button></div><div class="modalbody"><div class="notice">ⓘ 提交后将先进行机器敏感词审核，审核通过后进入人工审核。</div><div class="demo" style="display:none">审核场景 <button class="btn" onclick="fillDemo()">填入示例资料</button><select id="scenario" onchange="auditScenario=this.value"><option value="pass">正常内容 · 审核通过</option><option value="risk">风险内容 · 审核拦截</option><option value="error">模型服务异常</option></select></div><form id="registration" onsubmit="submitRegistration(event)"><div class="formgrid">${fields.map(field).join('')}<div class="field full" ${req('node.field.description')}><label class="required">业务简介</label><textarea name="description" required placeholder="请输入业务功能简介"></textarea></div><div class="field full" ${req('node.material')}><label class="required">核心业务证明材料</label><div class="content">${upload('上传证明材料','core')}</div></div><div class="field full"><label>证明材料文件名</label><input name="filename" placeholder="请输入业务功能证明材料文件名"></div><div class="field full" ${req('node.material')}><label>登记材料</label><div class="content" style="display:flex;justify-content:space-between"><div>${upload('上传营业执照','license')}</div><div>${upload('上传法人身份证','identity')}</div><div>${upload('上传服务承诺书','promise')}</div></div></div><div class="field full" ${req('node.templates')} style="align-items:flex-start"><label style="padding-top:15px">登记材料模板</label><div class="content"><div class="templates">${['营业执照模板','身份证模板','服务承诺书模板'].map((n,i)=>`<div class="template"><h3><span>${['▤','♙','♧'][i]}</span>${n}<a href="./template-${i}.txt" download>↓ 下载模板</a></h3><p>${['请下载营业执照模板，按格式准备企业营业执照副本扫描件或复印件，确保统一社会信用代码、企业名称、法定代表人等信息清晰可辨。','请下载身份证模板，按格式准备法定代表人身份证正反面扫描件或照片，确保姓名、身份证号码、有效期等关键信息完整清晰。','请下载服务承诺书模板，按照模板填写并加盖企业公章后上传，承诺书内容应包含服务内容、服务期限、责任义务等相关条款。'][i]}</p></div>`).join('')}</div><div class="tip">🟠 请下载模板后按要求填写，填写完成后将扫描件或照片上传至对应登记材料区域。模板仅供参考。</div></div></div><div class="field full" ${req('node.field.remark')}><label>备注</label><textarea name="remark" placeholder="请输入备注说明"></textarea></div><div class="field full" ${req('node.endpoint')} style="align-items:flex-start"><label class="required" style="padding-top:12px">业务节点地址</label><div class="content"><div id="addresses"></div><button type="button" class="link" onclick="addAddress()">＋ 添加地址</button></div></div></div></form></div><div class="modalfoot"><button class="btn" onclick="closeForm()">取消</button><button class="btn" onclick="saveDraft()">保存草稿</button><button class="btn primary" form="registration" type="submit" ${req('node.submit')}>提交审核</button></div></section></div>`;addAddress();const draft=sessionStorage.getItem('node-draft');if(draft){const d=JSON.parse(draft);for(const [k,v]of Object.entries(d)){const el=$(`[name="${k}"]`);if(el)el.value=v}}}
function addAddress(){const div=document.createElement('div');div.className='addresses';div.innerHTML='<select required name="endpointType"><option value="">地址类型</option><option>业务服务</option><option>数据服务</option></select><input required name="endpoint" type="url" pattern="https://.*" placeholder="服务地址(https://)"><input name="api" type="url" pattern="https://.*" placeholder="API地址(https://)"><button type="button" class="link" onclick="testConnection(this)">连接测试</button><button type="button" class="link" onclick="if($(\'#addresses\').children.length>1)this.parentElement.remove();else toast(\'至少保留一个地址\')">♜</button>';$('#addresses').append(div)}function testConnection(b){const v=b.parentElement.querySelector('[name=endpoint]');if(!v.checkValidity()||!v.value){v.reportValidity();return}b.textContent='测试中…';setTimeout(()=>{b.textContent='连接测试';toast('连接测试完成')},700)}function onFile(input,key){const f=input.files[0];if(!f)return;if(f.size>20*1024*1024){toast('单个文件不能超过20MB');input.value='';return}uploads[key]=f.name;$('#file-'+key).textContent=f.name;if(key==='core')$('[name=filename]').value=f.name}function closeForm(){if(confirm('关闭后未保存的修改将丢失，确认关闭？'))$('#overlay').innerHTML=''}function saveDraft(){sessionStorage.setItem('node-draft',JSON.stringify(Object.fromEntries(new FormData($('#registration')))));toast('草稿已保存到当前浏览器会话；附件需重新上传')}
function fillDemo(){const d={name:'区域数据协同服务节点',operator:'示例运营机构',org:'区域运营中心',credit:'91310000DEMO000001',service:'数据服务',version:'v1.0.0',date:'2026-10-30',legal:'示例联系人',phone:'13800138000',description:'提供区域数据目录检索与安全交换服务。',address:'示例区域数据中心',endpoint:'https://example.com',api:'https://example.com/api',endpointType:'数据服务'};for(const[k,v]of Object.entries(d))if($(`[name=${k}]`))$(`[name=${k}]`).value=v;uploads.core='核心业务证明材料.pdf';$('#file-core').textContent=uploads.core;$('[name=filename]').value=uploads.core;auditScenario=$('#scenario').value;toast('资料已填写')}
let pending;function submitRegistration(e){e.preventDefault();if(!uploads.core){toast('请上传核心业务证明材料');return}const d=Object.fromEntries(new FormData($('#registration')));if(!/^v?\d+\.\d+\.\d+$/.test(d.version)){toast('版本号格式应为 1.0.0 或 v1.0.0');return}pending={...d,uploads:{...uploads}};auditScenario=$('#scenario').value;const risk=/涉黄测试|涉暴测试|敏感词测试/.test([d.name,d.description,d.remark,...Object.values(uploads)].join(' '));showAudit('loading');setTimeout(()=>showAudit(auditScenario==='error'?'error':risk||auditScenario==='risk'?'risk':'pass'),1600)}
function showAudit(state){let layer=$('#audit');if(!layer){layer=document.createElement('div');layer.id='audit';layer.className='veil';layer.style.zIndex=30;document.body.append(layer)}const info={loading:['敏感词审核中','正在对登记文本与材料内容进行敏感词审核，请稍候。'],risk:['机器审核未通过','检测到风险，申请未提交至人工审核。'],error:['机器审核暂不可用','模型服务超时，申请尚未提交。请稍后重试。'],pass:['机器审核通过，提交成功','申请已进入人工审核队列，请等待审核结果。']}[state];layer.innerHTML=`<div class="auditbox" ${req('node.machineAudit')}>${state==='loading'?'<div class="loader"></div>':`<div class="auditmark" style="color:${state==='pass'?'#2e9f82':'#d69b3c'}">${state==='pass'?'✓':'!'}</div>`}<h2>${info[0]}</h2><p>${info[1]}</p><div class="auditsteps"><span>① 机器审核 ${state==='pass'?'✓':''}</span><span>→</span><span>② 人工审核 ${state==='pass'?'待处理':'未进入'}</span></div>${state==='risk'?'<div class="error">风险位置：业务简介 / 上传材料（演示）<br>风险类型：敏感词、涉黄或涉暴内容<br>请修改相关内容或替换材料后重新提交。<br>此结果来自演示场景，并非真实模型识别。</div>':state==='pass'?'<div class="success">机器审核：通过　｜　人工审核：待审核</div>':''}${state!=='loading'?`<p><button class="btn primary" onclick="finishAudit('${state}')">${state==='pass'?'完成':state==='risk'?'返回修改':'返回重试'}</button></p>`:''}</div>`;if(state==='pass'){rows.unshift({...pending});sessionStorage.removeItem('node-draft');$('#overlay').innerHTML='';section='review';render()}}
function finishAudit(state){$('#audit').remove()}function showDetail(i){const r=rows[i];$('#overlay').innerHTML=`<div class="veil"><div class="auditbox"><h2>接入登记详情</h2><p>${esc(r.name)}</p><div class="success">机器审核通过 · 待人工审核</div><p>所属组织：${esc(r.org)}<br>版本号：${esc(r.version)}<br>业务简介：${esc(r.description)}</p><button class="btn primary" onclick="$('#overlay').innerHTML=''">关闭</button></div></div>`}render();
