function catalogRender(){document.querySelector('header b').textContent='数据目录系统';$('#sidebar').innerHTML=`<div class="nav active" ${req('catalog.browse')} onclick="catalogTab='list';catalogRender()">▦　数据目录</div>`;$('#main').innerHTML=`<div class="systemtabs"><span onclick="section='launch';render()">首页</span><span class="selected">● 数据目录</span></div><div class="catalog"><div class="cat-toolbar"><span>${catalogTab==='detail'?'数据目录 / 数据目录详情':catalogTab==='logs'?'查询安全 / 查询日志':catalogTab==='alerts'?'查询安全 / 风险预警':catalogTab==='profile'?'查询安全 / 风险行为画像':'数据目录'}</span><div><button class="btn" onclick="catalogTab='list';catalogRender()">数据目录</button> <button class="btn" ${req('catalog.audit')} onclick="catalogTab='logs';catalogRender()">查询日志</button> <button class="btn" ${req('catalog.alert')} onclick="catalogTab='alerts';catalogRender()">风险预警 ${catalogAlerts.length?'('+catalogAlerts.length+')':''}</button> <button class="btn" ${req('catalog.profile')} onclick="catalogTab='profile';catalogRender()">风险画像</button></div></div><div id="catbody"></div></div>`;if(catalogTab==='list')catalogList();if(catalogTab==='detail')catalogDetail();if(catalogTab==='logs')catalogAudit();if(catalogTab==='alerts')catalogWarnings();if(catalogTab==='profile')catalogProfile()}
function catalogList(){ $('#catbody').innerHTML=`<section class="panel"><div class="cat-filters" ${req('catalog.query')} >${['产品类型','交互方式','产品名称','产品唯一标识','提供方名称','敏感等级'].map((n,i)=>`<label>${n}${[0,1,5].includes(i)?`<select id="cq${i}"><option value="">请选择</option>${(i===0?['数据报告','API产品']:i===1?['文件传输']:['公开','内部','机密']).map(x=>`<option>${x}</option>`).join('')}</select>`:`<input id="cq${i}" placeholder="请输入">`}</label>`).join('')}<div><button class="btn primary" onclick="catalogQuery()">⌕ 查询</button> <button class="btn" onclick="document.querySelectorAll('.cat-filters input,.cat-filters select').forEach(e=>e.value='');catalogResults()">↻ 重置</button></div></div></section><section class="panel cat-results"><aside><input placeholder="请输入行业分类" oninput="document.querySelectorAll('.industry').forEach(e=>e.hidden=!e.textContent.includes(this.value))">${industries.map(n=>`<div class="industry" onclick="this.parentNode.querySelectorAll('.industry').forEach(e=>e.classList.remove('chosen'));this.classList.add('chosen');catalogQuery()">${n}</div>`).join('')}</aside><div id="cat-results"></div></section><details class="cat-demo"><summary>安全场景验证</summary><p>当前演示身份：张明 / 重庆市文化和旅游发展委员会 / U1001；IP：192.0.2.18</p><button class="btn" onclick="queryTimes=Array.from({length:50},()=>Date.now());catalogQuery()">模拟第 51 次查询</button> <button class="btn" onclick="catalogQuery('permission')">模拟越权查询</button> <button class="btn" onclick="catalogQuery('token')">模拟令牌重放</button> <button class="btn" onclick="blockedUntil=0;queryTimes=[];toast('演示查询状态已恢复')">恢复演示查询</button><p>交互原型，未连接真实鉴权、网关和安全数据源。</p></details>`;catalogResults()}
function catalogResults(){const keyword=$('#cq2')?.value||'',type=$('#cq0')?.value||'';let found=products.map((name,i)=>({name,i})).filter(x=>x.name.includes(keyword)&&(!type||type===(x.i===3?'API产品':'数据报告'))&&(!$('#cq4').value||'中国移动通信集团重庆有限公司'.includes($('#cq4').value))&&(!$('#cq3').value||('691500000736550152L5000'+x.i).includes($('#cq3').value))&&(!$('#cq5').value||$('#cq5').value==='公开'));$('#cat-results').innerHTML=found.map(({name,i})=>`<article class="cat-product"><button class="link" style="float:right" ${req('catalog.detail')} onclick="catalogSelected=${i};catalogTab='detail';catalogRender()">查看详情</button><h3><span class="status">${i===3?'API产品':'数据报告'}</span>　${name}　<span class="status">文件传输</span></h3><p>产品简介：${i===0?productIntro:'围绕行业业务场景，分析客群特征、地域分布及活跃规律，为业务运营提供参考。'}</p><div class="cat-meta"><span>产品唯一标识：691500000736550152L5000${i}9D0G2KDI</span><span>数据资源标识码：[]</span><span>行业分类：信息传输、软件和信息技术服务业</span><span>提供方名称：中国移动通信集团重庆有限公司</span><span>提供方标识：91500000736550152L</span><span>登记完成时间：2026-10-26 16:32:03</span></div></article>`).join('')||'<div class="empty">暂无匹配的数据目录</div>';return found.length}
function catalogQuery(reason){let now=Date.now();queryTimes=queryTimes.filter(t=>now-t<60000);queryTimes.push(now);let why=blockedUntil>now?'高频访问阻断期':queryTimes.length>50?'高频访问':reason==='permission'?'越权访问':reason==='token'?'令牌重放':'';if(why.includes('高频'))blockedUntil=now+60000;let count=why?0:catalogResults();const id='Q'+now+'-'+catalogLogs.length;catalogLogs.unshift({id,time:new Date().toLocaleString('zh-CN'),ip:'192.0.2.18',user:'张明 / U1001',org:'重庆市文化和旅游发展委员会',target:$('#cq2')?.value||'全部数据目录',count,why,frequency:queryTimes.length,token:'jti-'+now,status:why?'已阻断':'成功'});if(why){catalogAlerts.unshift({id,why,time:new Date().toLocaleString('zh-CN'),state:'待研判'});$('#overlay').innerHTML=`<div class="veil"><div class="auditbox"><div class="auditmark" style="color:#d45353">!</div><h2>查询已被安全策略阻断</h2><p>${why.includes('高频')?'最近连续 60 秒查询 '+queryTimes.length+' 次，超过 50 次阈值。请在冷却期结束后重试。':why==='越权访问'?'当前身份无权查询该资源，请联系管理员核实权限。':'一次性令牌已使用，请重新认证后再查询。'}</p><p>请求编号：${id}<br>已记录审计轨迹并生成风险预警，本次未执行数据查询。</p><button class="btn primary" onclick="$('#overlay').innerHTML=''">我知道了</button></div></div>`}else toast('查询完成，返回 '+count+' 条目录，已记录审计日志')}
function catalogAudit(){ $('#catbody').innerHTML=`<section class="panel" ${req('catalog.audit')}><h3>查询日志</h3><div class="filters"><input id="logkey" placeholder="用户 / IP / 请求编号"><select id="logstatus"><option value="">全部结果</option><option>成功</option><option>已阻断</option></select><button class="btn primary" onclick="drawCatalogLogs()">查询</button><button class="btn" onclick="downloadCatalogLogs()">导出日志</button></div><p class="muted">当前会话 ${catalogLogs.length} 次查询 · 返回结果记录条数、状态与资源范围；不留存原始敏感数据和令牌原文。</p><table><thead><tr>${['查询时间','用户身份 / 机构','查询 IP','查询对象','返回结果','风险识别','操作'].map(n=>'<th>'+n+'</th>').join('')}</tr></thead><tbody id="catlogs"></tbody></table></section>`;drawCatalogLogs()}
function drawCatalogLogs(){let k=$('#logkey').value,st=$('#logstatus').value;$('#catlogs').innerHTML=catalogLogs.filter(r=>(r.user+r.ip+r.id+r.org).includes(k)&&(!st||st===r.status)).map(r=>`<tr><td>${r.time}<br><small>${r.id}</small></td><td>${r.user}<br><small>${r.org}</small></td><td>${r.ip}</td><td>${esc(r.target)}</td><td><span class="status ${r.why?'':'ok'}">${r.status}</span> ${r.count} 条</td><td>${r.why||'未发现异常'}</td><td><button class="link" onclick="catalogTrace('${r.id}')">全链路详情</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">暂无日志，请先在数据目录发起查询</td></tr>'}
function catalogTrace(id){let r=catalogLogs.find(x=>x.id===id);$('#overlay').innerHTML=`<div class="veil"><div class="auditbox" style="width:760px;text-align:left"><h2>查询全链路详情 <button class="close" onclick="$('#overlay').innerHTML=''">×</button></h2><p>${r.id} · ${r.time}</p><p>身份：${r.user}　机构：${r.org}<br>IP：${r.ip}　场景：本地查询　角色：政府部门<br>对象：${esc(r.target)}　密级：公开　令牌标识：${r.token}</p><ol class="trace"><li>请求接入：已生成请求编号</li><li>一次性令牌校验：${r.why==='令牌重放'?'失败 / 已使用':'通过 / 消费一次'}</li><li>ABAC 权限判定：${r.why==='越权访问'?'拒绝 / 资源范围不匹配':r.why==='令牌重放'?'未执行':'通过 / 公开目录可查询'}（策略 v1）</li><li>行为检测：${r.why||'正常'} / 连续 60 秒 ${r.frequency} 次</li><li>查询执行：${r.why?'未执行':'完成'}</li><li>结果返回：${r.status} / ${r.count} 条 / ${r.why?'HTTP 403 或 429':'HTTP 200'}<br>结果范围：目录元数据；敏感内容：无</li><li>审计归档：已记录${r.why?'，已关联风险预警':''}</li></ol><button class="btn" onclick="$('#overlay').innerHTML='';catalogTab='profile';catalogRender()">查看用户风险画像</button></div></div>`}
function catalogWarnings(){$('#catbody').innerHTML=`<section class="panel" ${req('catalog.alert')}><h3>风险识别与预警</h3><p class="muted">高频访问：同一用户连续 60 秒超过 50 次，实时阻断 60 秒；越权访问及令牌重放：立即拒绝并预警。</p><table><thead><tr><th>预警时间</th><th>风险行为</th><th>用户 / IP</th><th>风险等级</th><th>处置状态</th><th>操作</th></tr></thead><tbody>${catalogAlerts.map((a,i)=>`<tr><td>${a.time}</td><td>${a.why}</td><td>张明 / U1001<br>192.0.2.18</td><td><span class="status">高风险</span></td><td>${a.state}</td><td><button class="link" onclick="catalogTrace('${a.id}')">证据链</button> <button class="link" onclick="catalogResolve(${i})">研判处置</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">暂无预警</td></tr>'}</tbody></table></section>`}
function catalogResolve(i){$('#overlay').innerHTML=`<div class="veil"><div class="auditbox"><h2>风险研判</h2><select id="resolution"><option>确认风险</option><option>业务正常</option><option>规则误报</option></select><p><textarea id="resolutionNote" placeholder="填写研判依据（必填）"></textarea></p><button class="btn primary" onclick="if(!$('#resolutionNote').value.trim()){toast('请填写研判依据');return}catalogAlerts[${i}].state='已关闭 / '+$('#resolution').value;catalogAlerts[${i}].note=$('#resolutionNote').value;$('#overlay').innerHTML='';catalogRender()">保存处置</button> <button class="btn" onclick="$('#overlay').innerHTML=''">取消</button></div></div>`}
function catalogProfile(){let bad=catalogLogs.filter(x=>x.why).length;$('#catbody').innerHTML=`<section class="panel" ${req('catalog.profile')}><h3>张明 <span class="status">${bad?'高风险':'暂无风险'}</span></h3><p>U1001 · 政府部门 · 重庆市文化和旅游发展委员会</p><div class="summary"><article>查询总数<strong>${catalogLogs.length}</strong></article><article>异常查询<strong>${bad}</strong></article><article>返回目录条数<strong>${catalogLogs.reduce((n,r)=>n+r.count,0)}</strong></article><article>来源 IP 数<strong>${catalogLogs.length?1:0}</strong></article></div><h3>行为标签与证据</h3>${['高频访问','越权访问','令牌重放'].map(n=>`<p>${n}：${catalogLogs.filter(r=>r.why.includes(n)).length} 次</p>`).join('')}<p class="muted">统计范围：当前演示会话；每次查询后刷新。异常率 = 被阻断查询数 / 全部查询数；当前 ${catalogLogs.length?Math.round(bad/catalogLogs.length*100):0}%。风险标签依据命中规则生成，需结合业务背景人工研判。</p><button class="btn primary" onclick="catalogTab='logs';catalogRender()">查看关联查询证据</button></section>`}
function downloadCatalogLogs(){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({exportedAt:new Date().toISOString(),logs:catalogLogs,alerts:catalogAlerts},null,2)],{type:'application/json'}));a.download='查询审计日志.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function catalogDetail(){let entries=[['产品名称',products[catalogSelected]],['产品类型',catalogSelected===3?'API产品':'数据报告'],['覆盖时间范围','2026-01-01至2026-10-02'],['行业分类','信息传输、软件和信息技术服务业'],['地域分类','-'],['是否涉及个人信息','否'],['产品简介',productIntro],['交付方式','文件传输'],['使用限制','仅限授权用户使用，严禁转售、泄露或用于身份识别，违者承担法律责任'],['授权使用','是'],['数据主体','企业数据'],['数据规模','10 MB'],['更新频率','5 其他'],['产品唯一标识','691500000736550152L500039D0G2KDI'],['数据资源标识码','[]'],['其他','-'],['提供方名称','中国移动通信集团重庆有限公司'],['提供主体类型','法人'],['主体信息 JSON 字串','-'],['身份标识','91500000736550152L'],['提供方简介','重庆移动公司成立于2002年，提供通信与数智服务，支持数据流通和公共服务场景。'],['法人经办人姓名','-'],['法人经办人电话','-'],['法人经办人身份证','-'],['授权委托书','-'],['授权委托书名称','-'],['数据样例','-'],['数据样例（文件形式）名称','-'],['合法合规声明','重庆移动数据产品合法合规声明.pdf'],['合法合规声明（文件形式）名称','重庆移动数据产品合法合规声明.pdf'],['数据来源声明','重庆移动数据产品说明.pdf'],['数据来源声明（文件形式）名称','重庆移动数据产品说明.pdf'],['安全分级分类','-'],['安全分级分类（文件形式）名称','-'],['数据质量、产品价值评估报告','-'],['数据质量、产品价值评估报告（文件形式）名称','-']];$('#catbody').innerHTML=`<section class="panel" ${req('catalog.detail')}><h2 class="cat-title">基本信息</h2><div class="cat-detail">${entries.map(([k,v])=>`<div><span>${k}</span> ${esc(v)}</div>`).join('')}</div><p style="text-align:center"><button class="btn" onclick="catalogTab='list';catalogRender()">返回</button></p></section>`}

